  models?: {
    coder?: string
    evaluator?: string
    reviewer?: string
    planner?: string
  }
  /** URL used by browser-based tests (e.g. Playwright) */
  browserTestUrl?: string
  /** Webhook URL to notify on feature completion */
  webhookUrl?: string
  /** Enable TDD mode by default */
  tddMode?: boolean
  /** Enable review mode by default */
  reviewMode?: boolean
}

